  ('2', '5', '1', '1', NULL, '2020-06-15', '100.00', '15.00', '115.00', '0.00', '1', '2020-06-15 12:00:00.000000'),
  ('3', '5', '1', '99', NULL, '2020-06-15', '100.00', '15.00', '115.00', '0.00', '1', '2020-06-15 12:00:01.000000'),
  ('4', '5', '1', NULL, NULL, '2020-06-15', '100.00', '15.00', '115.00', '0.00', '1', '2020-06-15 11:00:00.000000'),
  ('5', '5', '1', NULL, NULL, '2020-06-15', '100.00', '15.00', '115.00', '0.00', NULL, '2020-06-15 13:00:00.000000');
INSERT INTO sales.invoices ("InvoiceID", "CustomerID") VALUES
  ('1', '8');
INSERT INTO purchasing.supplier_transactions ("SupplierTransactionID", "SupplierID", "TransactionTypeID", "PurchaseOrderID", "PaymentMethodID", "SupplierInvoiceNumber", "TransactionDate", "AmountExcludingTax", "TaxAmount", "TransactionAmount", "OutstandingBalance", "IsFinalized", "LastEditedWhen") VALUES
  ('1', '4', '5', NULL, '2', '', '2020-06-15', '-50.00', '-7.50', '-57.50', '-57.50', '0', '2020-06-15 12:00:00.000000'),
  ('2', '4', '5', '3', '2', 'INV-2', '2020-06-15', '-50.00', '-7.50', '-57.50', '0.00', '0', '2020-06-15 11:00:00.000001'),
  ('3', '4', '5', '3', '2', 'INV-3', '2020-06-15', '-50.00', '-7.50', '-57.50', '0.00', '0', '2020-06-15 13:00:00.000001');
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM integration.get_transaction_updates('2020-06-15 11:00:00.000000'::timestamp, '2020-06-15 13:00:00.000000'::timestamp);
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['Date Key', 'WWI Customer Transaction ID', 'WWI Supplier Transaction ID', 'WWI Invoice ID', 'WWI Purchase Order ID', 'Supplier Invoice Number', 'Total Excluding Tax', 'Tax Amount', 'Total Including Tax', 'Outstanding Balance', 'Is Finalized', 'WWI Customer ID', 'WWI Bill To Customer ID', 'WWI Supplier ID', 'WWI Transaction Type ID', 'WWI Payment Method ID', 'Last Modified When']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 customer id from the invoice when there is one, else from the transaction (no invoice, or an InvoiceI…', got, ARRAY['Date Key', 'WWI Customer Transaction ID', 'WWI Supplier Transaction ID', 'WWI Invoice ID', 'WWI Purchase Order ID', 'Supplier Invoice Number', 'Total Excluding Tax', 'Tax Amount', 'Total Including Tax', 'Outstanding Balance', 'Is Finalized', 'WWI Customer ID', 'WWI Bill To Customer ID', 'WWI Supplier ID', 'WWI Transaction Type ID', 'WWI Payment Method ID', 'Last Modified When']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('2020-06-15', '1', NULL, NULL, NULL, NULL, '100', '15', '115', '0', '1', '5', '5', NULL, '1', NULL, '2020-06-15 12:00:00.000000'),
  ('2020-06-15', '2', NULL, '1', NULL, NULL, '100', '15', '115', '0', '1', '8', '5', NULL, '1', NULL, '2020-06-15 12:00:00.000000'),
  ('2020-06-15', '3', NULL, '99', NULL, NULL, '100', '15', '115', '0', '1', '5', '5', NULL, '1', NULL, '2020-06-15 12:00:01.000000'),
  ('2020-06-15', '5', NULL, NULL, NULL, NULL, '100', '15', '115', '0', NULL, '5', '5', NULL, '1', NULL, '2020-06-15 13:00:00.000000'),
  ('2020-06-15', NULL, '1', NULL, NULL, '', '-50', '-7.5', '-57.5', '-57.5', '0', NULL, NULL, '4', '5', '2', '2020-06-15 12:00:00.000000'),
  ('2020-06-15', NULL, '2', NULL, '3', 'INV-2', '-50', '-7.5', '-57.5', '0', '0', NULL, NULL, '4', '5', '2', '2020-06-15 11:00:00.000001');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 customer id from the invoice when there is one, else from the transaction (no invoice, or an InvoiceI…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;
